package studio.milda.lang

import com.google.gson.Gson
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test
import java.io.File

// Parity gate for the gutter swatch. MildaColor.kt re-implements the DSL's colour literal
// grammar and the sRGB conversion that already exist in TypeScript, because a JVM plugin
// cannot call them. This test replays a fixture generated BY those TypeScript originals
// (`npm run gen:color-goldens`, see packages/core/foundations/genColorGoldens.ts): if the
// Kotlin twin reads a channel differently, scales a percentage differently, or gamut-maps
// differently, the hex it produces stops matching and this fails.
class MildaColorTest {
    private data class Golden(val literal: String, val space: String, val hex: String)

    @Test
    fun matchesTsGoldens() {
        val goldens = Gson().fromJson(fixture(), Array<Golden>::class.java)
        assertTrue("fixture is non-empty", goldens.isNotEmpty())
        // Every space the DSL can spell has to be covered, or the gate has a hole.
        assertEquals(
            setOf("srgb", "display-p3", "oklch", "hsl"),
            goldens.map { it.space }.toSet(),
        )
        for (golden in goldens) {
            val parsed = MildaColor.parse(golden.literal)
            assertNotNull("parses ${golden.literal}", parsed)
            assertEquals("sRGB of ${golden.literal}", golden.hex, MildaColor.toHex(parsed!!))
        }
    }

    @Test
    fun writesBackInTheAuthoredFunction() {
        // The picker hands back sRGB; each function keeps its own notation, and re-reading
        // what was written gives EXACTLY the colour that was picked - no drift, however many
        // times someone opens the picker. The primaries are the hard cases: they sit on the
        // sRGB gamut boundary, where too little precision reads back a byte off.
        val hard = listOf("#ff0000", "#00ff00", "#0000ff", "#ffffff", "#000000", "#3b82f6", "#010203")
        for (hex in hard) {
            val picked = MildaColor.parseHex(hex)!!
            for (fn in MildaColor.FUNCTIONS) {
                val written = MildaColor.format(fn, picked)
                assertTrue("$fn writes its own notation: $written", written.startsWith("$fn("))
                val reread = MildaColor.parse(written)
                assertNotNull("re-reads $written", reread)
                assertEquals("$hex round-trips through $written", hex, MildaColor.toHex(reread!!))
            }
        }
    }

    @Test
    fun keepsRoundValuesReadable() {
        // Generous precision must not mean noisy output: a colour that lands on round
        // channels still writes as one a person would have typed.
        assertEquals("srgb(1 1 1)", MildaColor.format("srgb", MildaColor.parseHex("#ffffff")!!))
        assertEquals("hsl(0 0% 0%)", MildaColor.format("hsl", MildaColor.parseHex("#000000")!!))
        assertEquals("rgb(255 128 0)", MildaColor.format("rgb", MildaColor.parse("rgb(255 128 0)")!!))
        assertEquals("hex(3b82f6)", MildaColor.format("hex", MildaColor.parseHex("#3b82f6")!!))
    }

    @Test
    fun keepsAlphaThroughAWriteBack() {
        val translucent = MildaColor.parse("srgb(0 0.5 1 / 0.25)")!!
        for (fn in MildaColor.FUNCTIONS) {
            val reread = MildaColor.parse(MildaColor.format(fn, translucent))!!
            assertEquals("alpha survives $fn", 0.25, reread.a, 0.005)
        }
    }

    @Test
    fun readsTheRawHexStringForm() {
        // `token legacy : color = raw "#00000000"` - the escape hatch, quotes and all.
        assertEquals("#0000ff", MildaColor.toHex(MildaColor.parseHex("\"#0000ff\"")!!))
        assertEquals("#ffffff", MildaColor.toHex(MildaColor.parseHex("#fff")!!))
        assertEquals("#ff000080", MildaColor.toHex(MildaColor.parseHex("#ff000080")!!))
        assertNull("a description is not a colour", MildaColor.parseHex("\"Trigger an action\""))
    }

    @Test
    fun refusesWhatIsNotAColour() {
        assertNull(MildaColor.parse("enum(S1, S2)")) // not a colour function
        assertNull(MildaColor.parse("hsl(210 50%)")) // too few channels
        assertNull(MildaColor.parse("oklch(0.62 nope 256)")) // unreadable channel
        assertNull(MildaColor.parse("hex(zzz)"))
        assertNull(MildaColor.parse("srgb 1 1 1")) // no parens
    }

    @Test
    fun formatsWithADecimalPointWhateverTheLocale() {
        // A decimal comma from a locale-sensitive formatter would silently turn one channel
        // into two and corrupt the file.
        val previous = java.util.Locale.getDefault()
        try {
            java.util.Locale.setDefault(java.util.Locale.forLanguageTag("hu-HU"))
            val written = MildaColor.format("oklch", MildaColor.parse("hex(3b82f6)")!!)
            assertTrue("no decimal comma in $written", !written.contains(','))
            assertEquals("#3b82f6", MildaColor.toHex(MildaColor.parse(written)!!))
        } finally {
            java.util.Locale.setDefault(previous)
        }
    }

    /** The fixture is a test resource, so it travels with the plugin in either repo. */
    private fun fixture(): String {
        val stream = javaClass.getResourceAsStream("/color-goldens.json")
        if (stream != null) return stream.bufferedReader().use { it.readText() }
        // Gradle test resources are on the classpath; fall back to the source path so the
        // failure reads as "regenerate the fixture" rather than "resource missing".
        val file = File("src/test/resources/color-goldens.json")
        assertTrue("run `npm run gen:color-goldens` (missing ${file.absolutePath})", file.isFile)
        return file.readText()
    }
}
